package pe.edu.upeu.inscripcion.service;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import pe.edu.upeu.inscripcion.dto.CertificadoDocumento;import java.time.LocalDateTime;import java.nio.file.*;import java.io.ByteArrayInputStream;import javax.imageio.ImageIO;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;
class CertificadoPdfServiceTest {
 @Test void generaA4ConNombresAcentuadosYExportaLaMismaPagina()throws Exception{
  var service=new CertificadoPdfService();var doc=new CertificadoDocumento("MODELO-SIN-VALIDEZ","María José Álvarez Muñoz (Ejemplo)","Programación profesional: desarrollo de aplicaciones web con Java, Spring y buenas prácticas de arquitectura",LocalDateTime.of(2026,10,27,18,0));byte[] pdf=service.generar(doc);try(var p=Loader.loadPDF(pdf)){assertEquals(1,p.getNumberOfPages());var page=p.getPage(0);assertTrue(page.getMediaBox().getWidth()>page.getMediaBox().getHeight());String texto=new PDFTextStripper().getText(p);assertTrue(texto.contains("María José Álvarez Muñoz"));assertTrue(texto.contains("Programación profesional"));assertTrue(texto.contains("MODELO-SIN-VALIDEZ"));assertTrue(texto.contains("FINALIZACIÓN"));for(var name:page.getResources().getFontNames())assertTrue(page.getResources().getFont(name).isEmbedded());}byte[] png=service.png(pdf);var imagen=ImageIO.read(new ByteArrayInputStream(png));assertTrue(imagen.getWidth()>1500);assertTrue(imagen.getHeight()>1000);Files.createDirectories(Path.of("target/revision-pdf"));Files.write(Path.of("target/revision-pdf/certificado-ejemplo.pdf"),pdf);Files.write(Path.of("target/revision-pdf/certificado-ejemplo.png"),png);
 }
}
